import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Value of each candidate times the slack it leaves (remaining - weight), normalised by the max."""
    s = values.astype(np.float64) * (remaining - weights).astype(np.float64)
    return s / (np.max(s) + 1e-9)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """How each candidate's weight compares to the average weight of the candidates still fitting, in units of remaining capacity."""
    k = len(weights)
    if k == 0:
        return np.zeros(0)
    mean_w = np.mean(weights)
    # spread of candidate weights: how far this item's weight sits from the crowd,
    # normalised by the remaining room so it matters most when space is tight.
    dev = (weights - mean_w) / (remaining + 1.0)
    return np.clip(dev, -1.0, 1.0)

