import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Candidate weight relative to the median weight of candidates still fitting, signed by whether it helps fill the remaining capacity (greedy-fit interaction)."""
    if len(weights) == 0:
        return np.zeros(0)
    med = np.median(weights)
    scale = max(capacity, 1)
    dev = (weights - med) / scale  # how unusual this item's weight is
    # interaction: an item is good if it moves us toward exactly filling `remaining`.
    fill = (remaining - weights) / max(remaining, 1)  # + if leaves slack, - if overshoots... but all fit so >=0
    # reward heavy items only when they don't leave too much slack relative to capacity
    return np.clip(dev * (0.5 - fill), -1.0, 1.0)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Fraction of other candidates that do NOT dominate the candidate (1 - dominators/(k-1))."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    k = v.shape[0]
    if k == 0:
        return np.zeros(0)
    dom = (v[None, :] >= v[:, None]) & (w[None, :] <= w[:, None]) & \
          ((v[None, :] > v[:, None]) | (w[None, :] < w[:, None]))
    cnt = dom.sum(axis=1).astype(float)
    return 1.0 - cnt / max(k - 1, 1)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Percentile rank of each candidate's density among the fitting candidates, centred at 0."""
    eps = 1e-9
    dens = values / (weights + eps)
    k = len(dens)
    if k < 2:
        return np.zeros(k)
    order = np.argsort(np.argsort(dens))          # 0..k-1 ranks, ties broken by index
    rank = order / (k - 1.0)                       # 0..1
    return np.clip(2.0 * rank - 1.0, -1.0, 1.0)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Residual value above the candidate set's own value-weight regression line, scaled by mean value."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    k = v.shape[0]
    if k < 2:
        return np.zeros(k)
    wm = w.mean()
    vm = v.mean()
    dw = w - wm
    dv = v - vm
    denom = float(np.sum(dw * dw))
    if denom <= 1e-9:
        return np.zeros(k)
    b = float(np.sum(dw * dv) / (denom + 1e-9))
    b = min(max(b, 0.0), 5.0)
    resid = dv - b * dw
    return np.clip(resid / (abs(vm) + 1e-9), -1.0, 1.0)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Reduced cost of each candidate: v - dbar*w, where dbar is the mean candidate density, scaled by max |rc| and clipped to [-1, 1]."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    k = v.shape[0]
    if k == 0:
        return np.zeros(0)
    d = v / np.maximum(w, 1.0)
    dbar = np.mean(d)
    rc = v - dbar * w
    scale = np.max(np.abs(rc)) + 1e-9
    return np.clip(rc / scale, -1.0, 1.0)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Signed relative difference between each candidate's value and the value of the best value-to-weight candidate still fitting."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    k = v.shape[0]
    if k == 0:
        return np.zeros(0)
    d = v / np.maximum(w, 1.0)
    j = int(np.argmax(d))
    vb = v[j]
    return np.clip((v - vb) / (abs(vb) + 1.0), -1.0, 1.0)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Value offered per unit of the binding constraint: candidate value relative to remaining capacity, minus its weight share of that capacity."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    k = v.size
    if k == 0:
        return np.zeros(0)
    rem = max(float(remaining), 1.0)
    # value efficiency against the scarce resource left, vs how much of it this item eats
    val_share = v / (np.mean(v) + 1e-9)
    wt_share = w / rem
    return np.clip(val_share - wt_share, -1.0, 1.0)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Candidate value relative to the best value-to-weight ratio available, scaled by how much of the remaining capacity the candidate would consume."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    if v.size == 0:
        return np.zeros(0)
    # density of each candidate, guarded
    dens = v / np.maximum(w, 1e-9)
    best_dens = float(np.max(dens))
    if best_dens <= 0:
        return np.zeros_like(v)
    # value share of the best-density item's value, weighted by capacity footprint
    best_idx = int(np.argmax(dens))
    best_val = float(v[best_idx])
    if best_val <= 0:
        return np.zeros_like(v)
    share = v / (best_val + 1e-9)
    footprint = w / (float(remaining) + 1e-9)
    return np.clip(share * footprint, 0.0, 1.0)

