import numpy as np
def feature(values, weights, remaining, capacity, taken):
    w = np.asarray(weights, dtype=float); v = np.asarray(values, dtype=float); k = w.size
    if k == 0: return np.zeros(0)
    eps = 1e-9; u = v - w; s = float(np.max(np.abs(u)))
    u_n = u / (s + eps) if s > 0 else np.zeros(k)
    r = float(remaining) - w
    if k >= 2:
        d = np.abs(r[:, None] - w[None, :]); np.fill_diagonal(d, np.inf); dmin = d.min(axis=1)
    else:
        dmin = r.copy()
    gate = 1.0 / (1.0 + dmin / (np.mean(w) + eps))
    gate = np.where(r <= eps, 1.0, gate)
    return np.clip(u_n * gate, -1.0, 1.0)
